"use client";

import { useState } from "react";
import { Check, Copy } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { analyticsMcp } from "@/lib/analytics";

type Client = "cursor" | "claude-code" | "vscode" | "codex" | "windsurf" | "gemini";
type Mode = "remote" | "local";

interface McpConfigTabsProps {
  baseUrl?: string;
  /** URL parameters to append (e.g., users, categories, tags) */
  queryParams?: string;
  className?: string;
  /** External mode control */
  mode?: "remote" | "local";
  onModeChange?: (mode: "remote" | "local") => void;
  /** Hide the mode toggle (when controlled externally) */
  hideModeToggle?: boolean;
  /** API key for authenticated access */
  apiKey?: string | null;
  /** Show official prompts.chat branding (VS Code buttons, registry mention) */
  showOfficialBranding?: boolean;
}

const CLIENT_LABELS: Record<Client, string> = {
  cursor: "Cursor",
  "claude-code": "Claude",
  vscode: "VS Code",
  codex: "Codex",
  windsurf: "Windsurf",
  gemini: "Gemini",
};

const NPM_PACKAGE =
  process.env.NEXT_PUBLIC_MCP_NPM_PACKAGE ?? "@fkadev/prompts.chat-mcp";
const MCP_SERVER_NAME =
  process.env.NEXT_PUBLIC_MCP_SERVER_NAME ?? "prompts.chat";
const MCP_TOML_KEY = MCP_SERVER_NAME.replace(/[^a-zA-Z0-9]/g, "_");

function buildLocalEnv(apiKey?: string | null, queryParams?: string): Record<string, string> | undefined {
  const env: Record<string, string> = {};
  if (apiKey) env.PROMPTS_API_KEY = apiKey;
  if (queryParams) env.PROMPTS_QUERY = queryParams;
  return Object.keys(env).length > 0 ? env : undefined;
}

/**
 * Wrap a value in POSIX single quotes so the shell treats it as a literal string,
 * preventing expansion of `$`, backticks, `"`, spaces, and other special characters.
 * Any embedded single quotes are replaced with the sequence `'\''`
 * (end single-quote, escaped quote, re-open single-quote).
 */
function shellEscape(value: string): string {
  return `'${value.replace(/'/g, "'\\''")}'`;
}

function getConfig(client: Client, mode: Mode, mcpUrl: string, apiKey?: string | null, queryParams?: string): string {
  const packageName = NPM_PACKAGE;
  const localEnv = buildLocalEnv(apiKey, queryParams);

  switch (client) {
    case "cursor":
      if (mode === "remote") {
        const config: Record<string, unknown> = {
          mcpServers: {
            [MCP_SERVER_NAME]: {
              url: mcpUrl,
              ...(apiKey && { headers: { "PROMPTS_API_KEY": apiKey } }),
            },
          },
        };
        return JSON.stringify(config, null, 2);
      } else {
        const config: Record<string, unknown> = {
          mcpServers: {
            [MCP_SERVER_NAME]: {
              command: "npx",
              args: ["-y", packageName],
              ...(localEnv && { env: localEnv }),
            },
          },
        };
        return JSON.stringify(config, null, 2);
      }

    case "claude-code":
      if (mode === "remote") {
        if (apiKey) {
          return `claude mcp add --transport http ${MCP_SERVER_NAME} "${mcpUrl}" --header ${shellEscape(`PROMPTS_API_KEY: ${apiKey}`)}`;
        }
        return `claude mcp add --transport http ${MCP_SERVER_NAME} "${mcpUrl}"`;
      } else {
        const envPrefix = localEnv 
          ? Object.entries(localEnv).map(([k, v]) => `${k}="${v}"`).join(" ") + " "
          : "";
        return `${envPrefix}claude mcp add ${MCP_SERVER_NAME} -- npx -y ${packageName}`;
      }

    case "vscode":
      if (mode === "remote") {
        const config: Record<string, unknown> = {
          mcp: {
            servers: {
              [MCP_SERVER_NAME]: {
                type: "http",
                url: mcpUrl,
                ...(apiKey && { headers: { "PROMPTS_API_KEY": apiKey } }),
              },
            },
          },
        };
        return JSON.stringify(config, null, 2);
      } else {
        const config: Record<string, unknown> = {
          mcp: {
            servers: {
              [MCP_SERVER_NAME]: {
                type: "stdio",
                command: "npx",
                args: ["-y", packageName],
                ...(localEnv && { env: localEnv }),
              },
            },
          },
        };
        return JSON.stringify(config, null, 2);
      }

    case "codex":
      if (mode === "remote") {
        if (apiKey) {
          return `[mcp_servers.${MCP_TOML_KEY}]
url = "${mcpUrl}"

[mcp_servers.${MCP_TOML_KEY}.headers]
PROMPTS_API_KEY = "${apiKey}"`;
        }
        return `[mcp_servers.${MCP_TOML_KEY}]
url = "${mcpUrl}"`;
      } else {
        let config = `[mcp_servers.${MCP_TOML_KEY}]
command = "npx"
args = ["-y", "${packageName}"]`;
        if (localEnv) {
          config += `\n\n[mcp_servers.${MCP_TOML_KEY}.env]`;
          for (const [key, value] of Object.entries(localEnv)) {
            config += `\n${key} = "${value}"`;
          }
        }
        return config;
      }

    case "windsurf":
      if (mode === "remote") {
        const config: Record<string, unknown> = {
          mcpServers: {
            [MCP_SERVER_NAME]: {
              serverUrl: mcpUrl,
              ...(apiKey && { headers: { "PROMPTS_API_KEY": apiKey } }),
            },
          },
        };
        return JSON.stringify(config, null, 2);
      } else {
        const config: Record<string, unknown> = {
          mcpServers: {
            [MCP_SERVER_NAME]: {
              command: "npx",
              args: ["-y", packageName],
              ...(localEnv && { env: localEnv }),
            },
          },
        };
        return JSON.stringify(config, null, 2);
      }

    case "gemini":
      if (mode === "remote") {
        if (apiKey) {
          return `PROMPTS_API_KEY=${shellEscape(apiKey)} gemini mcp add ${MCP_SERVER_NAME} --transport sse "${mcpUrl}"`;
        }
        return `gemini mcp add ${MCP_SERVER_NAME} --transport sse "${mcpUrl}"`;
      } else {
        const envPrefix = localEnv 
          ? Object.entries(localEnv).map(([k, v]) => `${k}="${v}"`).join(" ") + " "
          : "";
        return `${envPrefix}gemini mcp add ${MCP_SERVER_NAME} -- npx -y ${packageName}`;
      }

    default:
      return "";
  }
}

export function McpConfigTabs({ baseUrl, queryParams, className, mode, onModeChange, hideModeToggle, apiKey, showOfficialBranding = false }: McpConfigTabsProps) {
  const [selectedClient, setSelectedClient] = useState<Client>("vscode");
